horizontal"><dt><span class="fa fa-map-marker"> </span></dt><dd><span class="contact-street"><?php esc_html_e( '1600 Amphitheatre Parkway, Mountain View 5692', 'wp-ja-diner' ); ?></span></dd><dt><span class="fa fa-phone" aria-hidden="true"></span><span class="visually-hidden"><?php esc_html_e( 'Phone', 'wp-ja-diner' ); ?></span></dt><dd><span class="contact-telephone"><?php echo esc_html( '(084) 555-0110' ); ?></span></dd><dt><span class="fa fa-globe" aria-hidden="true"></span><span class="visually-hidden"><?php esc_html_e( 'Website', 'wp-ja-diner' ); ?></span></dt><dd><span class="contact-webpage"><a href="http://joomlart.com" target="_blank" rel="noopener noreferrer"> http://joomlart.com</a></span></dd></dl></div></div><div class="col-md-7"><div class="content-form-email"><h2><span><?php esc_html_e( 'Contact Form', 'wp-ja-diner' ); ?></span></h2><div class="container-form"><form id="contact-form" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" method="post" class="form-validate form-horizontal"><input type="hidden" name="action" value="jm_contact"><input type="hidden" name="jm_nonce" value="<?php echo esc_attr( wp_create_nonce( 'jm_contact' ) ); ?>"><div aria-hidden="true" style="position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden"><input type="text" name="jform[contact_url]" value="" tabindex="-1" autocomplete="off" aria-label="<?php esc_attr_e( 'Leave this field empty', 'wp-ja-diner' ); ?>"></div><fieldset><legend><?php esc_html_e( 'Send an Email. All fields with an asterisk (*) are required.', 'wp-ja-diner' ); ?></legend><div class="form-group"><div class="col-sm-6 contact-name"><label for="jform_contact_name" class="required col-sm-2 control-label"><?php esc_html_e( 'Name', 'wp-ja-diner' ); echo $jd_req; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- constant markup. ?></label><input type="text" name="jform[contact_name]" id="jform_contact_name" class="form-control required" size="30" maxlength="60" required autocomplete="name"></div><div class="col-sm-6 contact-email"><label for="jform_contact_email" class="required col-sm-2 control-label"><?php esc_html_e( 'Email', 'wp-ja-diner' ); echo $jd_req; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- constant markup. ?></label><input type="email" inputmode="email" name="jform[contact_email]" id="jform_contact_email" class="form-control validate-email required" size="30" maxlength="254" required autocomplete="email"></div></div><div class="form-group"><label for="jform_contact_emailmsg" class="required col-sm-2 control-label"><?php esc_html_e( 'Subject', 'wp-ja-diner' ); echo $jd_req; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- constant markup. ?></label><div class="col-sm-12"><input type="text" name="jform[contact_subject]" id="jform_contact_emailmsg" class="form-control required" size="60" maxlength="200" required></div></div><div class="form-group"><label for="jform_contact_message" class="required col-sm-2 control-label"><?php esc_html_e( 'Message', 'wp-ja-diner' ); echo $jd_req; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- constant markup. ?></label><div class="col-sm-12"><textarea name="jform[contact_message]" id="jform_contact_message" cols="50" rows="10" maxlength="5000" class="form-control required" required></textarea></div></div><div class="form-group"><div class="col-sm-6"></div><div class="col-sm-6"><div class="btn-send"><button class="btn btn-primary validate" type="submit"><?php esc_html_e( 'Send Email', 'wp-ja-diner' ); ?></button></div></div></div></fieldset></form></div></div></div></div></div></div></div></div></div></div>
